    alpha = 0.2
    if observation['action'] == 'cooperate':
        target = 1.0
    else:
        target = -1.0
    new_reputation = (1 - alpha) * current_reputation + alpha * target
    # Clamp to [-1.0, 1.0]
    return max(-1.0, min(new_reputation, 1.0))

